        /**
         * The relay URL if connected. `None` if disconnected.
         */relayUrl: String?, 
        /**
         * Round-trip latency to the relay in milliseconds. `None` if not measured.
         */latencyMs: Double?) {
        self.connected = connected
        self.relayUrl = relayUrl
        self.latencyMs = latencyMs
    }
}

